<script setup>
import {computed,ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,useAccount,notify,run} from '../lib'
const route=useRoute(),router=useRouter(),account=useAccount(),register=ref(false),busy=ref(false),captcha=ref({captchaId:'',image:''}),form=ref({username:'',password:'',nickname:'',captchaCode:''})
const admin=computed(()=>route.path==='/admin/login')
async function loadCaptcha(){try{captcha.value=await api.get('/captcha');form.value.captchaCode=''}catch{}}
onMounted(()=>run(loadCaptcha))
async function submit(){if(busy.value)return;busy.value=true;try{let payload={...form.value,captchaId:captcha.value.captchaId};if(register.value&&!admin.value){await api.post('/user/register',payload);notify('注册成功，请登录');register.value=false;return}let role=admin.value?'admin':'user';let data=await api.post('/'+role+'/login',payload);account.save(role,data);if(role==='user')account.refreshCart();router.push(admin.value?'/admin':String(route.query.redirect||'/'))}finally{busy.value=false;run(loadCaptcha)}}
</script>
<template><div class="login-page" :class="{merchant:admin}"><RouterLink to="/" v-if="admin" class="login-back"><Icon name="back"/> 返回花礼商城</RouterLink><div class="login-illustration"><img src="/images/bouquet-3.svg" alt="花束插画"/><div><span class="eyebrow">LIFE BLOOMS HERE</span><h2>日子因花，<br>温柔了几分。</h2></div></div><form class="login-form" @submit.prevent="run(submit)"><span class="eyebrow">{{admin?'FLEUR MERCHANT':'WELCOME TO FLEUR'}}</span><h1>{{admin?'商家工作台':register?'开启你的花礼日常':'好久不见，花正开。'}}</h1><p>{{admin?'登录后管理商品、订单与每一份心意。':'登录花礼，把美好送给重要的人。'}}</p><label>账号<input v-model="form.username" required minlength="4" maxlength="40" placeholder="4至40位字母、数字或下划线" autocomplete="username"/></label><label v-if="register&&!admin">昵称<input v-model="form.nickname" maxlength="60" placeholder="希望我们如何称呼你"/></label><label>密码<input v-model="form.password" type="password" required minlength="8" maxlength="72" placeholder="至少8位密码" :autocomplete="register?'new-password':'current-password'"/></label><label>图形验证码<div class="captcha-row"><input v-model="form.captchaCode" required maxlength="4" autocomplete="off" placeholder="输入图中字符"/><button type="button" class="captcha-img" @click="run(loadCaptcha)" aria-label="刷新验证码" title="点击刷新验证码"><img v-if="captcha.image" :src="captcha.image" alt="图形验证码"/><span v-else>加载中</span></button></div></label><button class="btn primary" :disabled="busy">{{busy?'请稍候…':register?'注册账号':'登录'}} <Icon name="arrow" :size="18"/></button><p v-if="!admin" class="login-switch">{{register?'已有账号？':'第一次来到花礼？'}}<button type="button" @click="register=!register">{{register?'去登录':'创建账号'}}</button></p><div class="demo-note">本地演示账号：<b>{{admin?'admin / Admin123!':'demo / Demo123!'}}</b><small>仅本地演示环境预置，正式部署请设置独立密码。</small></div></form></div></template>
